-- -------------------------------------------------------------------------
-- Change log.
-- -------------------------------------------------------------------------
CREATE TABLE dalet._change_log (
    change_log_id   BIGINT       GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    table_name      VARCHAR(63)  NOT NULL,
    operation       CHAR(1)      NOT NULL CHECK (operation IN ('I', 'U', 'D')),
    -- Text, not BIGINT: one log serves tables keyed by integer, bigint and
    -- composite business keys alike.
    row_key         VARCHAR(200) NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    changed_by      TEXT         NOT NULL DEFAULT current_user,
    -- Populated on delete only. Inserts and updates leave it null because
    -- the current row remains readable in the base table, and copying it
    -- would double the write volume of the busiest tables.
    old_row         JSONB
);

CREATE INDEX ix_dalet_change_log_changed_at
    ON dalet._change_log (changed_at);
CREATE INDEX ix_dalet_change_log_table
    ON dalet._change_log (table_name, changed_at);

COMMENT ON TABLE dalet._change_log IS
    'Change capture for incremental extraction. Deletes are the reason this '
    'exists: a high-water-mark read of updated_at cannot see a removed row.';

CREATE OR REPLACE FUNCTION dalet.log_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    -- TG_ARGV[0] names the key column, so one function serves every table.
    key_column TEXT := TG_ARGV[0];
    source_row JSONB;
BEGIN
    source_row := to_jsonb(COALESCE(OLD, NEW));

    INSERT INTO dalet._change_log (table_name, operation, row_key, old_row)
    VALUES (
        TG_TABLE_NAME,
        CASE TG_OP WHEN 'INSERT' THEN 'I' WHEN 'UPDATE' THEN 'U' ELSE 'D' END,
        COALESCE(source_row ->> key_column, '(unknown)'),
        CASE WHEN TG_OP = 'DELETE' THEN source_row ELSE NULL END
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;

COMMENT ON FUNCTION dalet.log_change() IS
    'Generic change logger. Pass the key column name as the trigger argument.';

-- Applied to the master and financial tables, where a missed delete would
-- leave an orphan in the target model. Deliberately not applied to
-- append-only high-volume tables: the write volume would double for no
-- benefit, since nothing ever deletes from them.
CREATE TRIGGER trg_media_object_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.media_object
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('media_object_id');
CREATE TRIGGER trg_essence_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.essence
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('essence_id');
CREATE TRIGGER trg_metadata_value_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.metadata_value
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('metadata_value_id');
CREATE TRIGGER trg_collection_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.collection
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('collection_id');
CREATE TRIGGER trg_job_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.job
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('job_id');
CREATE TRIGGER trg_rights_contract_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.rights_contract
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('rights_contract_id');
CREATE TRIGGER trg_rights_window_change
    AFTER INSERT OR UPDATE OR DELETE ON dalet.rights_window
    FOR EACH ROW EXECUTE FUNCTION dalet.log_change('rights_window_id');
